import React from "react";
import { Link } from "gatsby";

export type BannerImage = {
  src: string;
  srcSet?: string;
  alt: string;
};

export type BannerCrumb = {
  label: string;
  /** Omitted on the current page, which is text rather than a link. */
  to?: string;
};

export type ApplicationBannerProps = {
  image: BannerImage;
  eyebrow: string;
  title: string;
  lede: string;
  crumbs: BannerCrumb[];
  crumbLabel?: string;
};

/**
 * The banner at the top of the application page.
 *
 * Markup only — the photograph, the copy and the trail come from the primitive,
 * and the scrim, the type and the entrance are the template's. The entrance is
 * pure CSS rather than a mounted flag: this sits at the very top of the page,
 * so there is no scroll position to wait for and no reason to hold the first
 * paint behind React.
 */
export default function ApplicationBanner({
  image,
  eyebrow,
  title,
  lede,
  crumbs,
  crumbLabel = "Breadcrumb",
}: ApplicationBannerProps) {
  return (
    <section className="kr-apply-head">
      <div className="kr-apply-head__media">
        <img
          className="kr-apply-head__image"
          src={image.src}
          srcSet={image.srcSet}
          sizes={image.srcSet ? "100vw" : undefined}
          alt={image.alt}
          /* Largest paint on the page, and above the fold. */
          loading="eager"
          decoding="sync"
        />
        <span className="kr-apply-head__scrim" aria-hidden="true" />
      </div>

      <div className="kr-apply-head__inner">
        <div className="kr-apply-head__content">
          <span className="kr-apply-head__rule" aria-hidden="true" />
          <p className="kr-apply-head__eyebrow">{eyebrow}</p>
          <h1 className="kr-apply-head__title">{title}</h1>
          <p className="kr-apply-head__lede">{lede}</p>

          <nav className="kr-apply-head__crumbs" aria-label={crumbLabel}>
            <ol>
              {crumbs.map((crumb) => (
                <li key={crumb.label}>
                  {crumb.to ? (
                    <Link to={crumb.to}>{crumb.label}</Link>
                  ) : (
                    <span aria-current="page">{crumb.label}</span>
                  )}
                </li>
              ))}
            </ol>
          </nav>
        </div>
      </div>
    </section>
  );
}
