// Turns a set of form answers into the payload that gets encrypted and sent.
//
// This exists because the payload used to be a fixed shape — submissionId,
// message, siteId, name, phone, email — built by naming those fields directly.
// That was survivable while every form on the site asked the same three
// questions. It is not survivable now the Application Builder lets an editor
// add "Employment Status" or "Previous Address": those answers reached the
// submit handler and were dropped on the floor, silently, with the applicant
// told their application had been received.
//
// So: every answer is carried, and the canonical three are resolved rather
// than assumed. The leads pipeline keeps indexing and displaying on name,
// phone and email exactly as before.

export type SubmissionAnswers = Record<string, unknown>;

export type SubmissionForm = {
  /** Which application definition was filled in, when there is one. */
  id?: string;
  name?: string;
};

export type BuildSubmissionOptions = {
  submissionId: string;
  siteId: string;
  form?: SubmissionForm;
  /**
   * Field names to read the canonical values from, when a form uses names the
   * conventions below would not find. Rarely needed.
   */
  canonical?: { name?: string; email?: string; phone?: string };
};

export type Submission = {
  submissionId: string;
  siteId: string;
  /** Kept for the existing leads pipeline, which indexes and displays on these. */
  name: string;
  phone: string;
  email: string;
  /** A readable digest, so a lead is legible without the CMS. */
  message: string;
  form?: SubmissionForm;
  /** Every answer, exactly as configured. This is the part that used to be lost. */
  answers: SubmissionAnswers;
};

/**
 * Field names that conventionally hold each canonical value, best first.
 *
 * The contact form calls it `name`; the application form calls it `fullName`.
 * Rather than teach every form a mapping, look for what forms actually use.
 */
const CONVENTIONS = {
  name: ["name", "fullName", "full_name", "fullname", "applicantName"],
  email: ["email", "emailAddress", "email_address"],
  phone: ["phone", "phoneNumber", "phone_number", "tel", "telephone", "mobile"],
} as const;

/** Answers are strings or arrays of strings; render both for display. */
export function answerToText(value: unknown): string {
  if (value === undefined || value === null) return "";
  if (Array.isArray(value)) return value.map(answerToText).filter(Boolean).join(", ");
  if (typeof value === "boolean") return value ? "Yes" : "No";
  return String(value);
}

function resolve(
  answers: SubmissionAnswers,
  keys: readonly string[],
  explicit?: string
): string {
  if (explicit && answers[explicit] !== undefined) {
    return answerToText(answers[explicit]);
  }

  for (const key of keys) {
    const value = answers[key];
    if (value !== undefined && answerToText(value).trim() !== "") {
      return answerToText(value);
    }
  }

  return "";
}

/**
 * A human-readable summary of every answer.
 *
 * Previously this was hardcoded to `service` and `details`, which meant a form
 * without those fields produced "Interested in service: undefined". Built from
 * the answers instead, so it says something true whatever the form asks.
 */
export function buildMessage(
  answers: SubmissionAnswers,
  form?: SubmissionForm
): string {
  const lines = Object.entries(answers)
    .map(([key, value]) => {
      const text = answerToText(value).trim();
      return text ? `${key}: ${text}` : "";
    })
    .filter(Boolean);

  const heading = form?.name ? `${form.name}\n` : "";

  return `${heading}${lines.join("\n")}`.trim();
}

export function buildSubmission(
  answers: SubmissionAnswers,
  options: BuildSubmissionOptions
): Submission {
  // Copied, so a caller's object is never the one that gets sent or mutated.
  const carried: SubmissionAnswers = { ...answers };

  return {
    submissionId: options.submissionId,
    siteId: options.siteId,
    name: resolve(carried, CONVENTIONS.name, options.canonical?.name),
    phone: resolve(carried, CONVENTIONS.phone, options.canonical?.phone),
    email: resolve(carried, CONVENTIONS.email, options.canonical?.email),
    message: buildMessage(carried, options.form),
    ...(options.form ? { form: options.form } : {}),
    answers: carried,
  };
}
